def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Returns the minimum number of transformation steps if possible within 10 steps,
    otherwise returns "NO ANSWER!".
    """
    try:
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

    # Validate and filter the rules
    valid_rules = []
    for rule in rules:
        if isinstance(rule, tuple) and len(rule) == 2:
            src, tgt = rule
            if isinstance(src, str) and isinstance(tgt, str) and src:
                valid_rules.append((src, tgt))
    if not valid_rules:
        # No valid rules to apply
        return 0 if A == B else "NO ANSWER!"

    # BFS initialization
    queue = [(A, 0)]
    visited = set([A])
    max_steps = 10

    while queue:
        current, steps = queue.pop(0)
        if current == B:
            return steps
        if steps >= max_steps:
            continue
        for src, tgt in valid_rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # Move past this index to find overlapping matches
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """Generate all unique numbers reachable from n by applying digit transformation rules.

    Parameters
    ----------
    n : int
        The original integer number to transform.
    rules : list of tuples
        Each tuple (x, y) indicates digit x can be transformed into digit y.

    Returns
    -------
    int
        Count of unique numbers (including the original number) that can be generated.
    """
    # Basic input validation
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if not isinstance(rules, list):
        raise TypeError(f"rules must be a list, got {type(rules).__name__}")

    # Build mapping from each digit to list of possible replacements
    mapping = {}
    for rule in rules:
        if not (isinstance(rule, tuple) or isinstance(rule, list)) or len(rule) != 2:
            raise ValueError(f"Each rule must be a tuple/list of length 2, got {rule}")
        x, y = rule
        if not (isinstance(x, int) and isinstance(y, int)):
            raise ValueError(f"Rule digits must be integers, got ({x}, {y})")
        if not (0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError(f"Digits must be in [0,9], got ({x}, {y})")
        mapping.setdefault(str(x), []).append(str(y))

    from collections import deque

    start_str = str(abs(n))
    visited = set()
    visited.add(int(start_str))  # use integer representation to avoid leading zero duplicates
    queue = deque([start_str])

    while queue:
        cur_str = queue.popleft()
        for i, ch in enumerate(cur_str):
            if ch not in mapping:
                continue
            for repl in mapping[ch]:
                new_str = cur_str[:i] + repl + cur_str[i+1:]
                new_int = int(new_str)  # int conversion removes leading zeros
                if new_int not in visited:
                    visited.add(new_int)
                    queue.append(new_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluate if a given scenario (one participant being the criminal) is consistent
    with a set of statements, accounting for liars and ignoring day-of-week statements.

    Parameters:
        scenario (str): The name of the participant being tested as the potential criminal.
        liar_count (set): Set of names of participants who are assumed to be liars.
        statements (dict): Mapping from participant names to lists of their statements.
        days_of_week (set): Set of strings representing the days of the week.

    Returns:
        bool: True if the scenario is consistent with the statements, False otherwise.
    """
    try:
        # Normalize days of week to uppercase for case-insensitive comparison
        days_upper = {day.upper() for day in days_of_week}

        for speaker, speaker_statements in statements.items():
            for stmt in speaker_statements:
                # Skip statements containing any day-of-week keyword
                if any(day in stmt.upper() for day in days_upper):
                    continue

                stmt = stmt.strip()
                # Determine subject and claim of guilt/innocence
                truth = None  # Will be set to True or False

                # Handle "I am guilty." / "I am not guilty."
                if stmt.lower() in ("i am guilty.", "i am not guilty."):
                    subject = speaker
                    claim_guilty = stmt.lower() == "i am guilty."

                # Handle "{NAME} is guilty." / "{NAME} is not guilty."
                elif stmt.lower().endswith("is guilty.") or stmt.lower().endswith("is not guilty."):
                    parts = stmt.split()
                    if len(parts) >= 3:
                        # Extract subject (could be any name)
                        subject = parts[0]
                        claim_guilty = stmt.lower().endswith("is guilty.")
                    else:
                        # Malformed statement; skip
                        continue
                else:
                    # Unknown statement format; ignore
                    continue

                # Evaluate truth of the statement
                if claim_guilty:
                    truth = (subject == scenario)
                else:
                    truth = (subject != scenario)

                # If speaker is a liar, the statement must be false
                if speaker in liar_count:
                    if truth:
                        return False
                else:
                    if not truth:
                        return False

        return True
    except Exception:
        # In case of unexpected errors, consider the scenario inconsistent
        return False

